/**
 * Claude Code -> DeepSeek compatibility proxy.
 * Hoists role:"system" entries from messages[] into top-level `system`
 * (DeepSeek anthropic endpoint only accepts user/assistant in messages).
 */
import http from "node:http";
import https from "node:https";

const PORT = Number(process.env.DEEPSEEK_CC_PROXY_PORT || 18789);
const TARGET_HOST = "api.deepseek.com";

function contentToText(content) {
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((block) => {
      if (typeof block === "string") return block;
      if (block?.type === "text") return block.text ?? "";
      if (block?.type === "thinking") return block.thinking ?? "";
      return block?.text ?? block?.content ?? "";
    })
    .filter(Boolean)
    .join("\n");
}

function fixAnthropicBody(raw) {
  const data = JSON.parse(raw);
  if (!Array.isArray(data.messages)) return raw;

  const systemParts = [];
  if (data.system) {
    systemParts.push(
      typeof data.system === "string"
        ? data.system
        : contentToText(data.system)
    );
  }

  data.messages = data.messages.filter((msg) => {
    if (msg.role !== "system") return true;
    const text = contentToText(msg.content);
    if (text) systemParts.push(text);
    return false;
  });

  if (systemParts.length) {
    data.system = systemParts.join("\n\n");
  } else {
    delete data.system;
  }

  return JSON.stringify(data);
}

function forward(req, res, body) {
  let outBody = body;
  if (
    req.method === "POST" &&
    (req.url?.includes("/messages") || req.url?.includes("/complete"))
  ) {
    try {
      outBody = fixAnthropicBody(body);
    } catch {
      outBody = body;
    }
  }

  const headers = { ...req.headers, host: TARGET_HOST };
  delete headers["content-length"];
  headers["content-length"] = Buffer.byteLength(outBody);

  const path = req.url?.startsWith("/anthropic")
    ? req.url
    : `/anthropic${req.url || ""}`;

  const upstream = https.request(
    {
      hostname: TARGET_HOST,
      port: 443,
      path,
      method: req.method,
      headers,
    },
    (pres) => {
      res.writeHead(pres.statusCode ?? 502, pres.headers);
      pres.pipe(res);
    }
  );

  upstream.on("error", (err) => {
    res.writeHead(502, { "content-type": "text/plain; charset=utf-8" });
    res.end(`DeepSeek proxy upstream error: ${err.message}`);
  });

  upstream.end(outBody);
}

const server = http.createServer((req, res) => {
  const chunks = [];
  req.on("data", (c) => chunks.push(c));
  req.on("end", () => forward(req, res, Buffer.concat(chunks).toString("utf8")));
});

server.listen(PORT, "127.0.0.1", () => {
  process.stdout.write(
    `deepseek-cc-proxy listening on http://127.0.0.1:${PORT}/anthropic\n`
  );
});

